    and `base_url` (the Router base URL) are sent, never a provider key. The
    model id is account-specific and must come from `GET /v1/models`.
    """

    model: Optional[str] = Param(
        None,
        help=(
            "Router model id, e.g. `openai:gpt-4.1`. Valid ids come from "
            "`GET /v1/models` and are mutually exclusive with `models`."
        ),
    )
    models: Optional[list[str]] = Param(
        None,
        help=(
            "Ordered fallback list of 1-15 `provider:provider-model` candidates. "
            "Mutually exclusive with `model`."
        ),
    )
    allow_flex_tier: Optional[bool] = Param(
        None,
        help=(
            "Opt a request in or out of Router's lower-cost Flex capacity. "
            "Leave unset unless the target model is known to support it."
        ),
    )
    provider_timeout: Optional[float] = Param(
        None, help="Seconds allowed per provider call."
    )
    timeout_before_headers: Optional[float] = Param(
        None, help="Seconds to wait for the first streaming event."
    )
    metadata: Optional[dict] = Param(
        None,
        help="Short string labels (e.g. feature/team) used for spend attribution.",
    )

    def prepare_params(self, **kwargs):
        kwargs.pop("tools_pydantic", None)
        if "messages" in kwargs:
            kwargs["input"] = kwargs.pop("messages")

        if self.model and self.models:
            raise ValueError(
                "`model` and `models` are mutually exclusive on RouterChatOpenAI"
            )

        extra_body: dict[str, Any] = {}
        if self.models:
            extra_body["models"] = self.models
        if self.allow_flex_tier is not None:
            extra_body["allow_flex_tier"] = self.allow_flex_tier
        if self.provider_timeout is not None:
            extra_body["provider_timeout"] = self.provider_timeout
        if self.timeout_before_headers is not None:
            extra_body["timeout_before_headers"] = self.timeout_before_headers
        if self.metadata:
            extra_body["metadata"] = self.metadata

        params_ = {
            "model": None if self.models else self.model,
            "temperature": self.temperature,
            "max_output_tokens": self.max_tokens,
            "top_p": self.top_p,
            "frequency_penalty": self.frequency_penalty,
            "presence_penalty": self.presence_penalty,
            "tool_choice": self.tool_choice,
            "tools": self.tools,
            "top_logprobs": self.top_logprobs,
        }
        params = {k: v for k, v in params_.items() if v is not None}
        if extra_body:
            params["extra_body"] = extra_body
        params.update(kwargs)

        return params

    def openai_response(self, client, **kwargs):
        """Get the Router response (OpenAI Responses schema)"""
        params = self.prepare_params(**kwargs)
        return client.responses.create(**params)

    async def aopenai_response(self, client, **kwargs):
        params = self.prepare_params(**kwargs)
        return await client.responses.create(**params)

    def prepare_output(self, resp: dict) -> LLMInterface:
        """Convert a Responses-schema payload into LLMInterface"""
        additional_kwargs = {}
        content = ""
        tool_calls = []

        for item in resp.get("output") or []:
            if item.get("type") == "message":
                content += "".join(
                    part.get("text", "")
                    for part in (item.get("content") or [])
                    if part.get("type") == "output_text"
                )
            elif item.get("type") == "function_call":
                tool_calls.append(item)

        if tool_calls:
            additional_kwargs["tool_calls"] = tool_calls

        usage = resp.get("usage") or {}
        return LLMInterface(
            candidates=[content],
            content=content,
            total_tokens=usage.get("total_tokens", -1),
            prompt_tokens=usage.get("input_tokens", -1),
            completion_tokens=usage.get("output_tokens", -1),
            additional_kwargs=additional_kwargs,
            messages=[AIMessage(content=content)],
            logprobs=[],
        )

    def stream(
        self, messages: str | BaseMessage | list[BaseMessage], *args, **kwargs
    ) -> Iterator[LLMInterface]:
        client = self.prepare_client(async_version=False)
        input_messages = self.prepare_message(messages)
        resp = self.openai_response(
            client, messages=input_messages, stream=True, **kwargs
        )

        for event in resp:
            if getattr(event, "type", None) == "response.output_text.delta":
                yield LLMInterface(content=event.delta, logprobs=[])

    async def astream(
        self, messages: str | BaseMessage | list[BaseMessage], *args, **kwargs
    ) -> AsyncGenerator[LLMInterface, None]:
        client = self.prepare_client(async_version=True)
        input_messages = self.prepare_message(messages)
        resp = await self.aopenai_response(
            client, messages=input_messages, stream=True, **kwargs
        )

        async for event in resp:
            if getattr(event, "type", None) == "response.output_text.delta":
                yield LLMInterface(content=event.delta)


